@Composable fun KingZuluApp(){val context=androidx.compose.ui.platform.LocalContext.current;val prefs=remember{context.getSharedPreferences("king_zulu_presentation",android.content.Context.MODE_PRIVATE)};val wiredBridge=remember(context){WiredDisplayBridge(context)};val browserReceiver=remember(context){BrowserReceiverServer(context)};var tab by rememberSaveable{mutableStateOf("Bible")};var previewReference by rememberSaveable{mutableStateOf("")};var previewText by rememberSaveable{mutableStateOf("")};var previewTranslation by rememberSaveable{mutableStateOf("")};var previewKind by rememberSaveable{mutableStateOf("")};var presentation by remember{mutableStateOf(PreviewLiveState())};val initialTheme=remember{LocalBackgroundStore.loadSelected(context)};var previewTheme by remember{mutableStateOf(initialTheme)};var liveTheme by remember{mutableStateOf(initialTheme)};var textSize by rememberSaveable{mutableIntStateOf(prefs.getInt("text_size",32))};var autoFit by rememberSaveable{mutableStateOf(prefs.getBoolean("auto_fit",true))};val preview=if(previewKind.isBlank())null else PresentationSlide(previewReference,previewText,previewTranslation,previewKind);val live=presentation.live.slide;LaunchedEffect(live,presentation.live.black,liveTheme,textSize,autoFit){wiredBridge.render(live,presentation.live.black);browserReceiver.publish(live,presentation.live.black,liveTheme,textSize,autoFit)};DisposableEffect(wiredBridge,browserReceiver){onDispose{wiredBridge.dismiss();browserReceiver.stop()}};fun setPreview(s:PresentationSlide?){previewReference=s?.reference.orEmpty();previewText=s?.text.orEmpty();previewTranslation=s?.translation.orEmpty();previewKind=s?.kind.orEmpty();if(s!=null)presentation=presentation.preview(s)};fun setLive(s:PresentationSlide?){if(s!=null)liveTheme=previewTheme;presentation=presentation.present(s)};fun saveTextSettings(){prefs.edit().putInt("text_size",textSize).putBoolean("auto_fit",autoFit).apply()};val gallery=rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){uri->uri?.let{previewTheme=LocalBackgroundStore.importFromGallery(context,it)}};Scaffold(containerColor=KZBlack,topBar={Surface(color=KZBlack){Row(Modifier.fillMaxWidth().padding(18.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("KING ZULU",fontWeight=FontWeight.Black,fontSize=22.sp);Text("Worship presentation",color=KZMuted,fontSize=12.sp)};Text(if(live!=null||presentation.live.black)"● LIVE" else "○ READY",color=if(live!=null||presentation.live.black)KZLive else KZMuted,fontWeight=FontWeight.Black)}}},bottomBar={NavigationBar(containerColor=Color(0xFF101013)){listOf("Bible" to "B","Listen" to "L","Service" to "S","Media" to "M","Present" to "P","Outputs" to "O").forEach{(item,glyph)->NavigationBarItem(selected=tab==item,onClick={tab=item},icon={Text(glyph,fontWeight=FontWeight.Bold)},label={Text(item,fontSize=9.sp)})}}}){pad->Column(Modifier.padding(pad).fillMaxSize().verticalScroll(rememberScrollState()).padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){when(tab){"Bible"->BiblePanel({setPreview(it)},{setLive(it)},{tab="Translations"});"Translations"->BibleTranslationsPanel{tab="Bible"};"Listen"->AiListenPanel({setPreview(it)},{s->setPreview(s);setLive(s)});"Service"->ServicePanel(preview,{setPreview(it)},{s->setPreview(s);setLive(s)});"Media"->MediaPanel({setPreview(it)},{s->setPreview(s);setLive(s)});"Outputs"->DisplaysPanel(wiredBridge,browserReceiver);else->LivePanel(preview,live,presentation.live.black,presentation.history.isNotEmpty(),previewTheme,liveTheme,textSize,autoFit,{textSize=it;saveTextSettings()},{autoFit=it;saveTextSettings()},{setLive(it)},{presentation=presentation.black()},{presentation=presentation.previous()},{gallery.launch("image/*")})}}}}
