@Composable private fun PageHeading(title:String,subtitle:String){Text(title,fontSize=32.sp,fontWeight=FontWeight.Black);Text(subtitle,color=KZMuted,fontSize=14.sp)}
@Composable fun BiblePanel(onPreview:(PresentationSlide)->Unit,onGoLive:(PresentationSlide)->Unit,onTranslations:()->Unit){val context=androidx.compose.ui.platform.LocalContext.current;var q by rememberSaveable{mutableStateOf("")};var message by rememberSaveable{mutableStateOf("")};var selectedVerse by remember{mutableStateOf<Verse?>(null)};var chapter by remember{mutableStateOf(emptyList<Verse>())};var liveOnEnter by rememberSaveable{mutableStateOf(context.getSharedPreferences("king_zulu_bible",android.content.Context.MODE_PRIVATE).getBoolean("live_on_enter",false))};val translation=OfflineBibleRepository.selectedTranslation();val keyboard=LocalSoftwareKeyboardController.current;fun show(v:Verse,live:Boolean=liveOnEnter){selectedVerse=v;chapter=OfflineBibleRepository.chapter(v.reference.book,v.reference.chapter,v.translation);val s=PresentationSlide(v.reference.display(),v.text,v.translation);onPreview(s);if(live)onGoLive(s)};fun submit(){val v=BibleReferenceParser.parse(q)?.let{OfflineBibleRepository.get(it)};if(v!=null){message="";keyboard?.hide();show(v)}else message="Verse not found — check the reference"};PageHeading("Bible","Find Scripture fast.");SectionCard{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text(translation,fontSize=22.sp,fontWeight=FontWeight.Black);OutlinedButton(onTranslations){Text("BIBLES")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text(if(liveOnEnter)"⚡ LIVE ON ENTER" else "PREVIEW ON ENTER",fontWeight=FontWeight.Bold,color=if(liveOnEnter)KZLive else KZMuted);Switch(liveOnEnter,{liveOnEnter=it;context.getSharedPreferences("king_zulu_bible",android.content.Context.MODE_PRIVATE).edit().putBoolean("live_on_enter",it).apply()})};OutlinedTextField(q,{q=it;message=""},Modifier.fillMaxWidth(),singleLine=true,label={Text("Reference")},placeholder={Text("John 3:16")},keyboardOptions=KeyboardOptions(imeAction=ImeAction.Search),keyboardActions=KeyboardActions(onSearch={submit()}));Button({submit()},Modifier.fillMaxWidth()){Text(if(liveOnEnter)"FIND & GO LIVE" else "FIND VERSE")};if(message.isNotBlank())Text(message,color=KZPurpleSoft)};selectedVerse?.let{v->SectionCard{Text("${v.reference.book} ${v.reference.chapter}",fontSize=22.sp,fontWeight=FontWeight.Black);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){val idx=chapter.indexOfFirst{it.reference.verseStart==v.reference.verseStart};OutlinedButton({if(idx>0)show(chapter[idx-1])},enabled=idx>0,modifier=Modifier.weight(1f)){Text("‹ PREVIOUS")};OutlinedButton({if(idx>=0&&idx<chapter.lastIndex)show(chapter[idx+1])},enabled=idx>=0&&idx<chapter.lastIndex,modifier=Modifier.weight(1f)){Text("NEXT ›")}};chapter.forEach{cv->TextButton({show(cv)},Modifier.fillMaxWidth()){Text("${cv.reference.verseStart}. ${cv.text}",Modifier.fillMaxWidth())}};if(!liveOnEnter)Button({show(v,true)},Modifier.fillMaxWidth()){Text("GO LIVE")}}}}
@Composable fun MediaPanel(onPreview:(PresentationSlide)->Unit,onGoLive:(PresentationSlide)->Unit){var mode by rememberSaveable{mutableStateOf("Lyrics")};PageHeading("Media","Lyrics and countdown.");Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("Lyrics","Timer").forEach{item->if(mode==item)Button({mode=item},Modifier.weight(1f)){Text(item)}else OutlinedButton({mode=item},Modifier.weight(1f)){Text(item)}}};if(mode=="Lyrics")LyricsEditor(onPreview)else TimerEditor(onPreview,onGoLive)}
@Composable private fun LyricsEditor(onPreview:(PresentationSlide)->Unit){var text by rememberSaveable{mutableStateOf("")};SectionCard{OutlinedTextField(text,{text=it},Modifier.fillMaxWidth().height(220.dp),label={Text("Lyrics")});Button({if(text.isNotBlank())onPreview(PresentationSlide(text=text.lines().take(4).joinToString("\n"),kind="lyrics"))},Modifier.fillMaxWidth()){Text("PREVIEW")}}}
