@Composable fun LivePanel(preview:PresentationSlide?,live:PresentationSlide?,isBlack:Boolean,canPrevious:Boolean,previewTheme:BackgroundTheme?,liveTheme:BackgroundTheme?,textSize:Int,autoFit:Boolean,onTextSize:(Int)->Unit,onAutoFit:(Boolean)->Unit,setLive:(PresentationSlide?)->Unit,black:()->Unit,previous:()->Unit,chooseBackground:()->Unit){PageHeading("Present","Preview and audience control.");OperatorModeBar();Text("PREVIEW",color=KZMuted);Surface(shape=RoundedCornerShape(20.dp),color=Color.Black){PresentationCanvas(preview,previewTheme,Modifier.fillMaxWidth(),textSize,autoFit)};Button({setLive(preview)},enabled=preview!=null,modifier=Modifier.fillMaxWidth()){Text("GO LIVE")};SectionCard{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceBetween){Text("TEXT SIZE",fontWeight=FontWeight.Bold);Row{OutlinedButton({onTextSize((textSize-2).coerceAtLeast(14))}){Text("−")};Text(" $textSize ");OutlinedButton({onTextSize((textSize+2).coerceAtMost(60))}){Text("+")}}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text("AUTO FIT",fontWeight=FontWeight.Bold);Switch(autoFit,onAutoFit)}};Text("CURRENT LIVE",color=KZMuted);Surface(shape=RoundedCornerShape(20.dp),color=Color.Black){if(isBlack)Box(Modifier.fillMaxWidth().height(210.dp))else PresentationCanvas(live,liveTheme,Modifier.fillMaxWidth(),textSize,autoFit)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(black,Modifier.weight(1f)){Text("BLACK")};OutlinedButton({setLive(null)},Modifier.weight(1f)){Text("CLEAR")};OutlinedButton({setLive(PresentationSlide(text="KING ZULU",kind="logo"))},Modifier.weight(1f)){Text("LOGO")}};OutlinedButton(previous,enabled=canPrevious,modifier=Modifier.fillMaxWidth()){Text("↶ PREVIOUS LIVE")};OutlinedButton(chooseBackground,Modifier.fillMaxWidth()){Text("CHOOSE BACKGROUND")}}
